/**
 * The ids of orders whose stock number joined to NO `nsn_records` document.
 *
 * Recorded at generation time because a spec cannot re-derive it: an order that
 * joined to a record holding no code carries the same two nulls, and those are
 * DIFFERENT facts. A spec that told them apart by reading the nulls would be
 * asserting its own premise.
 */
export const LIVE_UNJOINED_IDS: readonly string[] = [
  "dibbs-live-000",
  "dibbs-live-022",
  "dibbs-live-other-000",
];
